Given an array arr[] of integers which may or may not contain duplicate elements. Your task is to remove duplicate elements. Your result should have elements according their first appearance in the input array.Examples: Input: arr[] = [1, 2, 3, 1, 4, 2]Output: [1, 2, 3, 4]Explanation: 2 and 1 have more than 1 occurence.Input: arr[] = [1, 2, 3, 4]Output: [1, 2, 3, 4]Explanation: There is no duplicate element.Try It YourselfTable of Content[Naive Approach] Using Nested loops - O(n^2) Time and O(1) Space[Expected Approach] Using Hash Set - O(n) Time and O(n) Space[Naive Approach] Using Nested loops - O(n^2) Time and O(1) SpaceUse two nested loops. The outer loop picks an element one by one starting from the leftmost element. The inner loop checks if the element is present on left side of it. If present, then ignore the element, else store it in result. 
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> removeDuplicate(vector<int> &arr)
{
    vector<int> res;

    for (int i = 0; i < arr.size(); i++)
    {

        // Check if this element is included in result
        int j;
        for (j = 0; j < i; j++)
            if (arr[i] == arr[j])
                break;

        // Include this element if not included previously
        if (i == j)
            res.push_back(arr[i]);
    }
    return res;
}
// Driver Code
int main()
{
    vector<int> arr = {1, 2, 3, 1, 4, 2};
    vector<int> res = removeDuplicate(arr);

    for (int ele : res)
        cout << ele << " ";
    return 0;
}


