    #include <iostream>
#include <unordered_set>
#include <vector>
using namespace std;

vector<int> removeDuplicate(vector<int> &arr)
{
    // Creates an empty hashset
    int n = arr.size();
    unordered_set<int> s;
    vector<int> v;

    // Traverse the input array
    for (int i = 0; i < n; i++)
    {
        // If not present, then put it in
        // hashtable and print it
        if (s.find(arr[i]) == s.end())
        {
            s.insert(arr[i]);
            v.push_back(arr[i]);
        }
    }
    return v;
}
// Driver Code
